 ],
 "summary": "Get statements for a given account",
 "description": "Return the statements for the account specified by the accountId, filtered on date range parameters as required.\nStatements MUST be returned in descending `OpeningDate` order, newest first. Where two statements share the same `OpeningDate`, `StatementId` SHOULD be used as a descending tiebreaker so that the ordering is stable.\nThe LFI must apply this ordering to the filtered result set before `page` and `page-size` are applied, so that page 1 always contains the most recent statements matching the request and a statement does not move between pages while a result set is being paged through.\n",
 "operationId": "getStatementsByAccountId",
