 },
 {
 "name": "accountId",
 "in": "path",
 "description": "Id of the account to be queried",
 "required": true,
 "schema": {
 "type": "string"
 }
 },
 {
 "$ref": "#/components/parameters/page"
 },
 {
 "$ref": "#/components/parameters/page-size"
 },
 {
 "in": "query",
 "name": "fromStatementDate",
 "description": "Start date for filtering of the Statements on the OpeningDate field. If this is not populated, the start date will be open ended",
 "schema": {
 "type": "string",
 "format": "date"
 }
 },
 {
 "in": "query",
 "name": "toStatementDate",
 "description": "End date for filtering of the Statements on the OpeningDate. If this is not populated, the end date will be open ended",
 "schema": {
 "type": "string",
 "format": "date"
 }
 }
 ],
